--region init
function ActivityNightCatChapterDialog:InitHandler()
    SetButtonAction(self.FontStyleButton, Bind(self, self.RightBtnOnClickHandler))
end

function ActivityNightCatChapterDialog:InitData()
    local argument = self.controller.Argument.parameters
    self:SetChapterData(argument.chapterDojo)
    self:SetChapterPlotData(ActivityNightCatMgr:GetChapterPlotData(self:GetChapterId()))
    if argument.plotId then
        for i, v in ipairs(self:GetChapterPlotData()) do
            if checkInt(v.id) == checkInt(argument.plotId) then
                if v.state == ActivityNightCatConstants.ChapterState.FINISH 
                    and checkTable(self:GetChapterPlotData()[i+1]).state == ActivityNightCatConstants.ChapterState.LOCK then
                    self:SetSelectedTab(i+1)
                else
                    self:SetSelectedTab(i)
                end
                break
            end
        end
    else
        for i, v in ipairs(self:GetChapterPlotData()) do
            if v.state ~= ActivityNightCatConstants.ChapterState.FINISH then
                self:SetSelectedTab(i)
                break
            end
        end
    end
end

function ActivityNightCatChapterDialog:InitView()
    self:InitPattern()
    self:InitPlotTab()
end

function ActivityNightCatChapterDialog:InitPlotTab()
    local tabScrList = {}
    for i, v in ipairs(self:GetChapterPlotData()) do
        local tabObj = GameObject.Instantiate(self.BtnPage.gameObject, self.ButtonGroup)
        local scr = CfUtils.GetLuaScr(tabObj, "Game.Activity.NightCat.ActivityNightCatPlotTabNode")
        if scr then
            scr:SetClickCallBack(function()
                if self:GetSelectedTab() == i then return end

                if i ~= 1 then
                    local data = self:GetChapterPlotData()[i-1]
                    if data.state ~= ActivityNightCatConstants.ChapterState.FINISH then
                        GameUtils.Toast(localize("关卡未解锁"))
                        return
                    end
                end
                self:RefreshPlotTab(i)
            end)
            scr:RefreshPattern(self:GetPrefabType())
            table.insert(tabScrList, scr)
        end
        
    end
    KTool.SetActive(self.BtnPage, false)
    self:SetTabScrList(tabScrList)
    self:RefreshPlotTab(self:GetSelectedTab())
end 

function ActivityNightCatChapterDialog:InitPattern()
    local type = self:GetPrefabType()
    CfUtils.SetUISwitchImage(self.ImgComicPages1, type)
    CfUtils.SetUISwitchImage(self.ImgComicPages2, type)
    CfUtils.SetUISwitchImage(self.ImgComicPages3, type)
    CfUtils.SetUISwitchImage(self.ImgComicPages4, type)
    CfUtils.SetUISwitchImage(self.ImgBook, type)
    CfUtils.SetUISwitchImage(self.ImgBook, type)
    CfUtils.SetUISwitchImage(self.ImgBubble, type)
end
