--region handler
---右侧按钮点击回调
function ActivityNightCatChapterDialog:RightBtnOnClickHandler()
    local data = self:GetSelectedChapterPlotData()
    if not data then return end

    if data.state == ActivityNightCatConstants.ChapterState.LOCK then
        -- 活动是否结束
        if ActivityNightCatMgr:CheckActivityEnded(true) then return end
        -- 解锁关卡
        if GoodsUtils.GetThingNo(data.unlockItem) < checkInt(data.unlockNum) then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.unlockItem)
            if vo then
                GameUtils.Toast(localize("_name_不足, 可通过挑战侵蚀空间获得", {_name_ = vo.name}))
            end
        else
            GameUtils.Request(Interfaces.ActivityNightUnlockPlot, {
                activityUuid = ActivityNightCatMgr:GetActivityId(),
                questId      = data.id
            }, Bind(self, self.UnlockPlotResponseHandler))
        end
    else
        -- 进入战斗
        ActivityNightCatMgr:EnterQuest(data.regionId)
        UIModule.CloseDialog(self.controller)
    end
end

---剧情解锁回调处理
function ActivityNightCatChapterDialog:UnlockPlotResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end
    
    -- 扣除消耗
    local data = self:GetSelectedChapterPlotData()
    local consume = {{
        goodsId = checkInt(data.unlockItem),
        num = -checkInt(data.unlockNum)
    }}
    GoodsUtils.DrawRewards(consume)
    
    -- 更新数据
    ActivityNightCatMgr:UnlockPlot(data.id)
    self:SetChapterPlotData(ActivityNightCatMgr:GetChapterPlotData(self:GetChapterId()))
    self:RefreshPlotTab()
    
    -- 解锁后直接进入关卡
    ActivityNightCatMgr:EnterQuest(data.regionId)
    UIModule.CloseDialog(self.controller)
end
--endregion handler

--region private
---刷新剧情UI
function ActivityNightCatChapterDialog:RefreshPlotUI()
    self:RefreshCover()
    self:RefreshBubble()
    self:RefreshBtnUI()
end

---刷新封面
function ActivityNightCatChapterDialog:RefreshCover()
    local path = self:GetSelectedChapterPlotData().plotImage
    CfUtils.FillImage(self.ImgCover, path)
end

---刷新气泡框
function ActivityNightCatChapterDialog:RefreshBubble()
    local plotData = self:GetSelectedChapterPlotData()
    CfUtils.FillText(self.TxtNumber, plotData.name)
    CfUtils.FillText(self.TxtDescribe, plotData.plotDesc)
end

---刷新按钮UI
function ActivityNightCatChapterDialog:RefreshBtnUI()
    local data = self:GetSelectedPlotData()
    if not data then return end

    if data.state == ActivityNightCatConstants.ChapterState.LOCK then
        CfUtils.FillText(self.FontStyleButtonText, localize("解锁"))
        KTool.SetActive(self.CommonBtnConsumePop, true)
        CfUtils.RefreshTopGoods({data.unlockItem})
        CfUtils.FillCommonBtnConsumePopNode(self.CommonBtnConsumePop, data.unlockItem, data.unlockNum)
    elseif data.state == ActivityNightCatConstants.ChapterState.UNLOCK then
        CfUtils.FillText(self.FontStyleButtonText, localize("继续"))
        KTool.SetActive(self.CommonBtnConsumePop, false)
        CfUtils.RefreshTopGoods({})
    elseif data.state == ActivityNightCatConstants.ChapterState.FINISH then
        CfUtils.FillText(self.FontStyleButtonText, localize("回顾"))
        KTool.SetActive(self.CommonBtnConsumePop, false)
        CfUtils.RefreshTopGoods({})
    end
end

---刷新剧情页签
---@param selectedTab integer 选中的页签（为空时仅刷新不执行动画）
function ActivityNightCatChapterDialog:RefreshPlotTab(selectedTab)
    local tabScrList = self:GetTabScrList()
    local chapterPlotData = self:GetChapterPlotData()
    local curSelectedTab = self:GetSelectedTab()
    local prefabType = self:GetPrefabType()

    for i, v in ipairs(tabScrList) do
        local data = checkTable(chapterPlotData[i])
        v:RefreshState(data.state)
        if data.state == ActivityNightCatConstants.ChapterState.LOCK then
            v:RefreshBgPattern(999)
        elseif data.state == ActivityNightCatConstants.ChapterState.UNLOCK then
            local index = selectedTab ~= nil and selectedTab or curSelectedTab
            if i == index then
                v:RefreshBgPattern(prefabType * 2 - 1)
            else
                v:RefreshBgPattern(prefabType * 2)
            end
        elseif data.state == ActivityNightCatConstants.ChapterState.FINISH then
            local index = selectedTab ~= nil and selectedTab or curSelectedTab
            if i == index then
                v:RefreshBgPattern(prefabType * 2 - 1)
            else
                v:RefreshBgPattern(prefabType * 2)
            end
        end
    end

    if selectedTab then
        if tabScrList[curSelectedTab] then
            tabScrList[curSelectedTab]:DeSelectAnimation()
        end

        if tabScrList[selectedTab] then
            tabScrList[selectedTab]:SelectAnimation()
        end
        self:SetSelectedTab(selectedTab)
    end
    self:RefreshPlotUI()
end

